window.PAPERS_DATA = {"meta": {"generated": "2026-08-07 22:02 UTC", "model": "deepseek-v4-pro", "n_papers": 82, "n_journals": 21, "n_journals_tracked": 43, "new_badge_days": 7}, "papers": [{"id": "W7172489643", "doi": "10.3102/00028312261466662", "title": "Shifting Futures: Trends in Socioeconomic Disparities in Adolescents’ Expected Occupational Status in the United States and the United Kingdom, 2000–2018", "date": "2026-08-05", "year": 2026, "journal": "American Educational Research Journal", "authors": ["Soo‐yong Byun", "Janice Kim", "Suyoung Park", "Sujin Kim"], "cited_by": 0, "abstract": "Using data from the Programme for International Student Assessment 2000–2018, this study examined trends in adolescents’ expected occupational status, socioeconomic status (SES) gradients, and distributional SES differentials in the United States and the United Kingdom. Guided by Turner’s distinction between contest and sponsored mobility systems, we found rising occupational expectations in both countries. SES gradients remained relatively stable in the United States but weakened in the United Kingdom, although this decline became less pronounced after accounting for academic achievement. Distributional analyses revealed persistent upper-end SES compression in the United States and narrowing upper-end gaps in the United Kingdom. Cross-national differences diminished over time, highlighting the role of mobility regimes and institutional contexts in shaping occupational expectations.", "first_seen": "2026-08-07", "relevance_type": "direct", "confidence": 0.95, "categories": ["educational_equity", "education_policy_society"], "reason": "Directly examines socioeconomic disparities in adolescents' occupational expectations, a core topic in educational equity."}, {"id": "W7172494440", "doi": "10.1016/j.econedurev.2026.102829", "title": "For a few dollars more: Compensatory spending in schooling", "date": "2026-08-05", "year": 2026, "journal": "Economics of Education Review", "authors": ["Matías Morales Cerda"], "cited_by": 0, "abstract": "", "first_seen": "2026-08-07", "relevance_type": "direct", "confidence": 0.65, "categories": ["educational_equity", "education_policy_society"], "reason": "The paper likely examines compensatory spending in schooling, directly addressing educational equity through resource allocation."}, {"id": "W7172257730", "doi": "10.1038/s41562-026-02523-3", "title": "Negative influence of early social media use on school outcomes", "date": "2026-08-03", "year": 2026, "journal": "Nature Human Behaviour", "authors": [], "cited_by": 0, "abstract": "", "first_seen": "2026-08-04", "relevance_type": "direct", "confidence": 0.8, "categories": ["educational_equity", "learning_science"], "reason": "Directly investigates how early technology use (social media) affects school outcomes, relevant to technology impacts on learning and potential disparities in education."}, {"id": "W7172301053", "doi": "10.1007/s10648-026-10204-w", "title": "Promoting Engagement in Elementary School: A Systematic Review and Meta-Analysis of Intervention Effects", "date": "2026-08-03", "year": 2026, "journal": "Educational Psychology Review", "authors": ["Julie Goulet", "Isabelle Archambault", "Christine Maltais", "Ophélie Gilbert-Blanchard", "Michel Janosz"], "cited_by": 0, "abstract": "", "first_seen": "2026-08-04", "relevance_type": "direct", "confidence": 0.8, "categories": ["educational_equity", "learning_science"], "reason": "Systematic review and meta-analysis on interventions to promote student engagement in elementary school, directly relevant to educational equity and learning science."}, {"id": "W7172247481", "doi": "10.1177/00380407261470787", "title": "Feeling the Best Fit: The Role of Emotions in College Decisions", "date": "2026-08-03", "year": 2026, "journal": "Sociology of Education", "authors": ["Madison Garcia"], "cited_by": 0, "abstract": "Using ethnographic observations and interviews with students and staff in a college access nonprofit (CAN), I show that college-going inequalities may also reflect structurally based emotional barriers and that these barriers can be overcome through opportunities to imagine futures with positive emotional valences where the student “fits” in college, and where college is a “fit” for the student. Before joining the CAN, students aspired to attend college, but their sense of fit was low and grounded in negative emotions (e.g., worries about challenges, ambivalence about college choices). Through CAN-sponsored college visits and precollege career-opportunity programs, students were able to imagine futures where they fit in college and where college fit their goals—imagining futures with positive emotional associations. This sense of fit allowed students to confidently make emotionally informed decisions about colleges and majors. I argue emotional barriers play an underdiscussed role in college transitions and clarify how emotions, by undergirding college decisions, shape youths’ paths to college.", "first_seen": "2026-08-04", "relevance_type": "direct", "confidence": 0.95, "categories": ["educational_equity"], "reason": "Examines how emotional barriers contribute to college-going inequalities, directly relevant to educational equity research."}, {"id": "W4404303599", "doi": "10.1016/j.cedpsych.2026.102487", "title": "Primary and secondary school students’ academic achievement trajectories before and during COVID-19", "date": "2026-08-01", "year": 2026, "journal": "Contemporary Educational Psychology", "authors": ["Kathryn Everhart Chaffee", "Marion Deslandes Martineau", "Isabelle Plante", "Patrick Charland"], "cited_by": 0, "abstract": "", "first_seen": "2026-08-04", "relevance_type": "direct", "confidence": 0.9, "categories": ["educational_equity", "learning_science"], "reason": "The title indicates a study of academic achievement trajectories before and during COVID-19, directly addressing educational equity and learning outcomes in primary and secondary education."}, {"id": "W7171850150", "doi": "10.1111/bjet.70080", "title": "Hybrid intelligence feedback systems in design thinking development: Stage‐specific insights on pedagogical effects and characteristics of generative <scp>AI<\/scp> and instructors", "date": "2026-07-30", "year": 2026, "journal": "British Journal of Educational Technology", "authors": ["Xiao Fei"], "cited_by": 0, "abstract": "Abstract Fostering design thinking relies on instructional feedback, yet traditional instructor‐led methods face practical limitations. Although generative AI (GenAI) may offer promising solutions based on its advantages, existing studies predominantly characterise it as a performance‐enhancing task assistant rather than as a feedback‐providing pedagogical agent for the intrinsic growth of design thinking. The study compares the pedagogical effects on students' design thinking and students' perceptions of feedback systems by GenAI and human instructors. A within‐class randomised experimental design was conducted with 80 undergraduates. Results indicate no significant overall difference in learning gains, but reveal respective stage‐specific strengths: GenAI proved more effective during the ‘empathise’ stage, associated with superior timeliness and privacy, while human instructors excelled in the ‘prototype’ stage, valued for their contextual anchoring. Comparable effects yet complementary functions were observed in other stages, reinforcing GenAI's augmentative role instead of substitution. Findings collectively demonstrate that the effectiveness and strengths of feedback systems are not static and uniform but dynamically aligned with the learning demands across educational settings. Practical insights for designing hybrid intelligence feedback systems and theoretical implications were finally discussed. Practitioner notes What is already known about this topic Instructional feedback is crucial for fostering design thinking; however, traditional instructor‐led feedback is often constrained by issues of scalability, timeliness and consistency. Generative AI (GenAI) shows promise to serve as an additional feedback agent, but its role has been explored more as a performance‐enhancing task assistant rather than a feedback‐providing pedagogical agent for the intrinsic growth of design thinking. What this paper adds The study demonstrates that GenAI leads to greater learning gains in the ‘empathise’ stage, while human instructors are more effective in the ‘prototype’ stage. The study underscores their comparable effect while serving distinct and complementary roles at ‘define’, ‘ideate’ and ‘reflect’ stages. The study highlights their respective stage‐specific strengths and associates them with learning gains across the design thinking process. The study provides practical insights for designing hybrid feedback systems that strategically orchestrate GenAI and human instructors to maximise pedagogical impact. Implications for practice and/or policy Educational policy should promote the design of hybrid feedback systems that strategically align the inherent characteristics of different feedback agents with the stage‐specific learning demands across various educational contexts. Curriculum development should emphasise building students' relevant competencies (e.g., feedback literacy, AI competency, etc.), equipping them to seek, evaluate and synthesise input from multiple agents effectively.", "first_seen": "2026-07-31", "relevance_type": "direct", "confidence": 0.95, "categories": ["ai_in_education", "learning_science"], "reason": "Directly compares generative AI and instructor feedback in design thinking education, providing insights for hybrid AI-instructor systems for learning."}, {"id": "W7171738457", "doi": "10.3102/0013189x261466211", "title": "The Racial Positioning of Asian Americans in Education Policy Research: Implications for Practice", "date": "2026-07-29", "year": 2026, "journal": "Educational Researcher", "authors": ["Sonia Giebel", "anthony lising antonio", "David Shuang Song"], "cited_by": 0, "abstract": "How does the education policy literature contribute to Asian Americans’ standing in educational equity discourse? We systematically analyze all articles published in Educational Evaluation and Policy Analysis from 2000 to 2024 to understand the “racial positioning” of Asian Americans: whether they are included in empirical study and alongside which groups they are categorized. We find that Asian Americans are increasingly absent from education policy research, despite population growth, and are instead more likely to be classified alongside White Americans—positionings that fortify Asian American invisibility and model minority tropes. These findings are not artifacts of data availability. We call on researchers to correct the current state of Asian American invisibility in the literature and thoughtfully account for the implications of racial positioning in their work.", "first_seen": "2026-07-31", "relevance_type": "direct", "confidence": 0.95, "categories": ["educational_equity", "education_policy_society"], "reason": "The paper directly examines racial positioning and invisibility of Asian Americans in education policy research, contributing to educational equity discourse and informing equitable policy practice."}, {"id": "W7171654905", "doi": "10.3102/01623737261454707", "title": "“It’s Like Separate but Equal”: Families and the Dual Nature of Disability in Special Education Policy", "date": "2026-07-28", "year": 2026, "journal": "Educational Evaluation and Policy Analysis", "authors": ["Adai Tefera", "LaRon A. Scott", "Evandra Catherine"], "cited_by": 0, "abstract": "Special education policies are intended to uphold the civil rights of students with disabilities, yet onerous administrative and racialized burdens, including excessive paperwork, jargon filled legal documents, and organizational barriers contribute to persistent inequities. In this qualitative case study, the administrative and racialized burdens faced by nondominant families and their children with disabilities were examined. Findings demonstrate the ways these burdens are patterned (a) inequitable access to special education services given the ways White families who utilized whiteness as a credential to obtain essential services; (b) the racialization of perceived “desirable” disability classifications based on families’ abilities to leverage multiple forms of capital; and (c) racially disparate access to high-quality, inclusive special education placements.", "first_seen": "2026-07-31", "relevance_type": "direct", "confidence": 0.95, "categories": ["educational_equity", "education_policy_society"], "reason": "Directly examines racial and socioeconomic disparities in access to special education services, aligning with the researcher's focus on educational equity."}, {"id": "W7171519039", "doi": "10.1038/d41586-026-02348-0", "title": "Conversational AI: align commercial incentives with public interests", "date": "2026-07-28", "year": 2026, "journal": "Nature", "authors": ["Yafei Si"], "cited_by": 0, "abstract": "", "first_seen": "2026-07-29", "relevance_type": "direct", "confidence": 0.75, "categories": ["ai_in_education", "educational_equity", "education_policy_society"], "reason": "Aligning conversational AI with public interests directly concerns fairness, bias, and societal impact, which are central to AI in education and educational equity."}, {"id": "W7171561915", "doi": "10.1080/10508406.2026.2688307", "title": "Learning what learning is: how classroom discourses shape Latine immigrant children’s ideas about learning", "date": "2026-07-28", "year": 2026, "journal": "Journal of the Learning Sciences", "authors": ["Molly E. McManus", "Marie‐Anne Suizzo"], "cited_by": 0, "abstract": "", "first_seen": "2026-07-29", "relevance_type": "direct", "confidence": 0.9, "categories": ["learning_science", "educational_equity"], "reason": "Examines how classroom discourse shapes learning conceptions among immigrant children, directly relevant to learning and educational equity."}, {"id": "W7171552251", "doi": "10.1016/j.econedurev.2026.102819", "title": "School-based support staff and chronic absenteeism: Evidence from North Carolina", "date": "2026-07-28", "year": 2026, "journal": "Economics of Education Review", "authors": ["Sarah Komisarow"], "cited_by": 0, "abstract": "", "first_seen": "2026-07-29", "relevance_type": "direct", "confidence": 0.7, "categories": ["educational_equity"], "reason": "The paper examines school-based support staff and chronic absenteeism, directly addressing educational equity through factors affecting attendance disparities."}, {"id": "W7171396226", "doi": "10.3102/01623737261449256", "title": "Examining the Impact of Performance-Based Funding Policy Designs on College Completion by Field of Study", "date": "2026-07-27", "year": 2026, "journal": "Educational Evaluation and Policy Analysis", "authors": ["Junghee Choi", "William Zahran", "Justin C. Ortagus", "Kelly Ochs Rosinger", "Hope Allchin", "Robert Kelchen"], "cited_by": 0, "abstract": "Amid rising concerns about the return on investment (ROI) of postsecondary education, an increasing number of states have adopted performance-based funding (PBF) metrics that focus on students’ economic success and completion in high-demand fields, such as science, technology, engineering, and mathematics (STEM) and health. States have also increased the share of state funding tied to PBF. In this study, we examine the effects of various PBF policy designs on student completion across different postsecondary credential types and academic fields. Our findings indicate that PBF policies did not have a significant impact on completion for certificates, associate degrees, or bachelor’s degrees across fields of study. These results remained consistent across institution types and students’ racial/ethnic background.", "first_seen": "2026-07-28", "relevance_type": "direct", "confidence": 0.95, "categories": ["educational_equity", "education_policy_society"], "reason": "Directly examines the impact of state funding policies on college completion across fields and by race/ethnicity, addressing educational equity."}, {"id": "W7170360194", "doi": "10.1016/j.learninstruc.2026.102432", "title": "Concrete images, diverse ideas: The role of pictures in learning from multimedia texts of varying abstractness", "date": "2026-07-25", "year": 2026, "journal": "Learning and Instruction", "authors": ["Ekaterina Blinova", "Olga Shcherbakova"], "cited_by": 0, "abstract": "", "first_seen": "2026-07-25", "relevance_type": "direct", "confidence": 0.9, "categories": ["ai_in_education", "learning_science"], "reason": "Investigates the role of pictures in learning from multimedia texts, directly informing the design of AI-generated educational content and tutoring systems."}, {"id": "W7170491449", "doi": "10.1016/j.compedu.2026.105726", "title": "Incorporating pedagogical agents into desktop virtual reality: Does visual-tone emotional congruency matter?", "date": "2026-07-24", "year": 2026, "journal": "Computers & Education", "authors": ["Shufan Yu", "Qingtang Liu", "Yuwei Jiang", "Jingjing Ma", "Yingying Peng", "Ruiqiu Ye", "Ping Li"], "cited_by": 0, "abstract": "", "first_seen": "2026-08-05", "relevance_type": "direct", "confidence": 0.9, "categories": ["ai_in_education", "learning_science"], "reason": "The title explicitly mentions pedagogical agents in virtual reality, which are AI-driven educational tools, and examines emotional congruency, directly relevant to AI in education and learning science."}, {"id": "W7170132259", "doi": "10.1016/j.iheduc.2026.101105", "title": "An empirical study of ChatGPT use in engineering education: Prompting and performance", "date": "2026-07-24", "year": 2026, "journal": "The Internet and Higher Education", "authors": ["Lauren Genith Isaza Domínguez", "Antonio Robles-Gómez", "Rafael Pastor-Vargas"], "cited_by": 0, "abstract": "", "first_seen": "2026-08-01", "relevance_type": "direct", "confidence": 0.9, "categories": ["ai_in_education"], "reason": "The title indicates a study on ChatGPT use in an educational context (engineering education), focusing on prompting and performance, which is directly relevant to AI in education."}, {"id": "W7170814194", "doi": "10.1016/j.compedu.2026.105725", "title": "I hear you: Enhancing middle school mathematics engagement and learning outcomes through teachable agent voice design", "date": "2026-07-24", "year": 2026, "journal": "Computers & Education", "authors": ["Hai Li", "Wanli Xing", "Chenglu Li", "Bailing Lyu"], "cited_by": 0, "abstract": "", "first_seen": "2026-08-01", "relevance_type": "direct", "confidence": 0.95, "categories": ["ai_in_education", "learning_science"], "reason": "The paper examines how voice design in teachable agents (a form of AI tutoring system) affects engagement and learning outcomes in middle school mathematics, directly aligning with AI in education research."}, {"id": "W7170185619", "doi": "10.1038/s44159-026-00600-y", "title": "Autistic students face ableism in the classroom", "date": "2026-07-23", "year": 2026, "journal": "Nature Reviews Psychology", "authors": ["Olivia Guy-Evans"], "cited_by": 0, "abstract": "", "first_seen": "2026-07-25", "relevance_type": "direct", "confidence": 0.9, "categories": ["educational_equity"], "reason": "Directly addresses inequity and discrimination against autistic students in classrooms, a core educational equity issue."}, {"id": "W7170156181", "doi": "10.1037/dev0002243", "title": "Two paths in persistence: Course and career motivations develop distinctly and relate to different precursors to career pursuit in college physics.", "date": "2026-07-23", "year": 2026, "journal": "Developmental Psychology", "authors": ["Emily Q. Rosenzweig", "Patrick N. Beymer", "Katherine Muenks", "Trevor T. Tuma"], "cited_by": 0, "abstract": "In trying to motivate college students toward career paths in science, technology, engineering, and mathematics (STEM), many scholars and policy-makers focus on promoting students' course-or fieldrelated motivation.However, STEM fields each contain dozens of careers, the nuances of which are not often discussed during STEM coursework itself.Further, many students change career plans while remaining highly motivated for studying particular STEM courses or fields.In order to understand career plan development, it may be important to understand the development of college students' career-specific motivation and how career motivational beliefs uniquely relate to STEM participation.The present study examined the development of course and career-related motivation, side by side across one semester, in a group of 738 college physics students.Results showed that (a) course and career motivation were empirically distinct, (b) course and career motivation developed mostly separately from one another across one semester of college, (c) course motivation was more strongly associated with students' final physics grades, whereas career motivation was more strongly associated with career satisfaction and certainty, and (d) there were unique gender differences in career motivation compared to course motivation.Together, findings suggest that course motivation and career motivation likely develop along separate, though interrelated, pathways during college, each of which uniquely contributes to different aspects of STEM career persistence (foundational knowledge and skills, vs. career-specific exploration).In order to foster STEM participation and equity, scholars and educators should complement course-focused motivational supports with supports for career motivational development across college. Public Significance StatementMany educators and researchers try to motivate college students to pursue science, technology, engineering, and mathematics (STEM) careers by trying to help students feel more motivated to engage with their STEM courses (e.g., biochemistry class) or fields of study (e.g., biology).Our study shows that this focus may not be complete, because it does not account for students' motivation for specific careers within fields in STEM (e.g., being a doctor).We found that course and career motivation in a college physics course developed separately over one semester of college, and the two types of motivation also predicted separate outcomes associated with STEM career choices.This implies that course motivation alone does not predict STEM career choices; instead, students also have to develop career-specific motivation during college in order to feel satisfied with and prepared for a STEM career after graduating.Educators and scholars should focus on studying and helping students develop their career motivation as a key goal in promoting STEM career persistence.", "first_seen": "2026-07-25", "relevance_type": "direct", "confidence": 0.95, "categories": ["educational_equity", "learning_science"], "reason": "The paper directly examines educational equity by investigating gender differences in career motivation and how supporting career-specific motivation can promote STEM participation and equity, a core equity concern in education."}, {"id": "W7170164073", "doi": "10.3102/00028312261461613", "title": "Creating a Vision for Improved Systems of School Mental Health Through Youth Participatory Action Research: A School Mental Health Policy Rubric", "date": "2026-07-23", "year": 2026, "journal": "American Educational Research Journal", "authors": ["Kate Somerville"], "cited_by": 0, "abstract": "This study used critical policy analysis and youth participatory action research to engage 12 high school students in critically examining and reimagining systems of school mental health policy and practice in U.S. public schools. Through a series of 10 online meetings, youth researchers from diverse school communities across the country collected and analyzed data from their own schools and communities, drawing on their differing lived experiences and identities to collaboratively develop a school mental health policy rubric . The rubric contains seven policy recommendations grounded in a critical prevention framework, centering power shifts and equity as essential to promoting youth thriving. Findings highlight the value of youth expertise in designing school mental health systems that meet young people’s needs.", "first_seen": "2026-07-25", "relevance_type": "direct", "confidence": 0.95, "categories": ["educational_equity", "education_policy_society"], "reason": "Directly addresses educational equity through youth-led policy recommendations for school mental health systems."}, {"id": "W7170161207", "doi": "10.1037/dev0002240", "title": "The development of in-group-favoring math stereotypes among adolescents across gender and race/ethnicity: Teacher influence and motivational consequences.", "date": "2026-07-23", "year": 2026, "journal": "Developmental Psychology", "authors": ["Hyewon Lee", "Glona Lee", "Jacquelynne S. Eccles", "Sandra D. Simpkins"], "cited_by": 0, "abstract": "= 0.63 in nineth grade), we found that Asian and White girls' female-favoring math stereotypes and their perceived math teacher support reinforced one another from early to late adolescence, but not among other groups. In-group-favoring math stereotypes positively predicted math motivational beliefs among boys across all racial/ethnic groups, but only among Black and White girls. These stereotypes indirectly predicted math grade point average (GPA) via motivational beliefs only for White adolescents. Findings suggest that gender differences in the development of in-group-favoring math stereotypes and the benefits of stereotype lift are not the same across race/ethnicity. Rather, gender norms that vary across different racial/ethnic groups may shape who develops and benefits from in-group-favoring math stereotypes, underscoring the need to consider intersectionality to better capture motivational processes in real-world contexts. (PsycInfo Database Record (c) 2026 APA, all rights reserved).", "first_seen": "2026-07-25", "relevance_type": "direct", "confidence": 0.95, "categories": ["educational_equity", "education_policy_society"], "reason": "This study directly examines intersectional educational equity by analyzing how gender and race/ethnicity shape math stereotypes, teacher support, and motivational outcomes among adolescents."}, {"id": "W7170187250", "doi": "10.1016/j.learninstruc.2026.102436", "title": "Tell me how: Teaching science with narration vs exposition", "date": "2026-07-23", "year": 2026, "journal": "Learning and Instruction", "authors": ["Sara Soares", "João O. DOS SANTOS", "Cláudia Simão", "Matilde Gonçalves", "Raquel Barata", "Rita Jerónimo", "Régine Kolinsky"], "cited_by": 0, "abstract": "", "first_seen": "2026-07-25", "relevance_type": "direct", "confidence": 0.8, "categories": ["learning_science"], "reason": "Investigates instructional methods (narration vs exposition) for teaching science, directly contributing to learning science research."}, {"id": "W7170187458", "doi": "10.3102/0013189x261468334", "title": "A Framework for Facilitating Young People’s Sociocritical AI Literacies", "date": "2026-07-23", "year": 2026, "journal": "Educational Researcher", "authors": ["Golnaz Arastoopour Irgens", "Sarah K. Burriss"], "cited_by": 0, "abstract": "As artificial intelligence (AI) becomes increasingly embedded in young people’s lives, there is an urgent need for conceptual educational frameworks that sufficiently integrate technical skills with the ethical and social implications of AI. This essay proposes a sociocritical AI literacies framework centered on four interrelated components—being, knowing, acting, and making—to support children and youth in developing technical critical consciousness, computational knowledge, and collective agency. Drawing from traditions in critical pedagogy and critical literacy studies, this actionable framework emphasizes identity, justice, and creativity, positioning young people not as passive users but as capable co-creators of more equitable AI futures. This approach calls for educators and communities to take children and youth perspectives seriously and holistically in reimagining technosocial learning environments.", "first_seen": "2026-07-25", "relevance_type": "direct", "confidence": 1.0, "categories": ["ai_in_education", "educational_equity"], "reason": "Proposes a sociocritical AI literacies framework for young people that integrates AI technical skills with social justice and equity, directly addressing AI in education and educational equity."}, {"id": "W7170031509", "doi": "10.1016/j.learninstruc.2026.102423", "title": "Facilitating autistic student voice in reasonable adjustments", "date": "2026-07-22", "year": 2026, "journal": "Learning and Instruction", "authors": ["Delyse Clayden", "Narelle Lemon", "Susan Main"], "cited_by": 0, "abstract": "", "first_seen": "2026-07-25", "relevance_type": "direct", "confidence": 0.9, "categories": ["educational_equity"], "reason": "Directly addresses inclusive education by facilitating autistic student participation in reasonable adjustments, a core equity issue."}, {"id": "W7169827902", "doi": "10.1073/pnas.2612021123", "title": "Children’s books about scientists convey demotivating messages", "date": "2026-07-21", "year": 2026, "journal": "Proceedings of the National Academy of Sciences", "authors": ["Jessica R. Gladstone", "Gabrielle Applebaum", "Andrei Cimpian"], "cited_by": 0, "abstract": "Biographies of scientists are widely used to spark children's interest and broaden participation in science. In telling the stories of successful scientists, these books convey implicit \"recipes for success\"-yet no study has systematically examined whether these recipes align with what motivation research recommends. Here, we provide the first large-scale analysis of motivational messages in children's science biographies (422 best-selling books, 1,355 protagonists). Four main findings emerged. First, scientific ability was portrayed equally often as fixed and as malleable, a pattern unlikely to support motivation. Second, interest in science was overwhelmingly portrayed as fixed: Most scientists were said to be captivated by science from a young age. Third, scientists in physics, engineering, and computer science were portrayed as more reliant on fixed ability than scientists in other fields. Fourth, biographies of female scientists disproportionately emphasized effort even after adjusting for the obstacles they faced, consistent with stereotypes attributing women's success to hard work over talent. These findings suggest that well-intentioned efforts to diversify science through role model exposure in children's science biographies may fall short.", "first_seen": "2026-07-25", "relevance_type": "direct", "confidence": 0.95, "categories": ["educational_equity"], "reason": "Directly addresses educational equity by analyzing how children's science books convey motivational messages that may demotivate underrepresented groups, impacting participation and inclusion in STEM."}, {"id": "W7169830519", "doi": "10.3102/0013189x261467754", "title": "Visualizing Racism: Towards a QuantCrit Epistemic Network Analysis", "date": "2026-07-21", "year": 2026, "journal": "Educational Researcher", "authors": ["Nichole M. Garcia", "Brendan Eagan"], "cited_by": 0, "abstract": "This essay introduces “QuantCrit epistemic network analysis” (QENA), a methodological approach that integrates quantitative critical race theory (QuantCrit), Quantitative ethnography (QE), and epistemic network analysis (ENA) to examine how race and ethnicity inform meaning-making in education research. Drawing on W. E. B. Du Bois’s legacy of empirical visual storytelling, the essay explores how computational tools can make racialized meaning-making visible. QENA challenges dominant statistical norms and centers racially and multiply marginalized communities’ epistemologies to advance an anti-racist methodology by visualizing how they navigate, interpret, and resist structural racism through discourse.", "first_seen": "2026-07-25", "relevance_type": "direct", "confidence": 0.95, "categories": ["educational_equity", "methods_for_education_research"], "reason": "Proposes a methodological approach to examine racialized meaning-making in education, directly addressing educational equity and anti-racist methodology."}, {"id": "W7169875034", "doi": "10.3102/0013189x261466234", "title": "Refusing Educational Technology: Artificial Intelligence, Inequity, and the Problem of Critical Optimism", "date": "2026-07-21", "year": 2026, "journal": "Educational Researcher", "authors": ["Niral Shah", "David Stroupe", "Aman Yadav", "Tess Bernhard", "Charles Logan", "Elizabeth Dyer", "Peng He", "Christina Krist", "Tingting Li"], "cited_by": 0, "abstract": "Artificial intelligence (AI)—like many technologies before—comes with hope and worry about its implications for education. In this essay, using generative AI as a case, we appraise the ideological field of positions that stakeholders take in relation to educational technology overall. Drawing on science and technology studies, our analysis shows that education’s default position is optimism, even among those genuinely “critical” of technology’s capacity to amplify inequity. Refusal is not widely regarded as a legitimate response to educational technology. We argue, in contrast, that given the potential for scalable harm from unproven technologies like generative AI, the most rational position with new technology is robust caution with a readiness to refuse. We conclude by detailing three forms of refusal for educational stakeholders to consider: curricular, bureaucratic, and administrative.", "first_seen": "2026-07-25", "relevance_type": "direct", "confidence": 0.95, "categories": ["ai_in_education", "educational_equity"], "reason": "The paper directly analyzes AI in education, its implications for equity, and argues for refusal as a rational response to unproven technologies like generative AI."}, {"id": "W7169806593", "doi": "10.1073/pnas.2509764123", "title": "Race-conscious admissions algorithms and the law", "date": "2026-07-20", "year": 2026, "journal": "Proceedings of the National Academy of Sciences", "authors": ["Alexandra Chouldechova", "Daniel J. Hemel"], "cited_by": 0, "abstract": "In recent years, colleges and universities have begun to use machine learning (ML) systems to inform admissions decisions. Meanwhile, in the 2023 case Students for Fair Admissions, Inc. v. President and Fellows of Harvard College , the Supreme Court held that colleges and universities may not make admissions decisions “on the basis of race.” These parallel developments—the rise of ML in admissions and the fall of race-based affirmative action—will force educational institutions, and ultimately courts, to confront the difficult question of what it means for ML systems to differentiate “on the basis of race.” We begin by mapping the Students for Fair Admissions decision onto different uses of race in predictive AI. We distinguish between “first-order” and “second-order” race consciousness at both the training and predictive phases of machine learning, and we argue that each category of race consciousness raises distinct legal and normative issues. We go on to show that the Students for Fair Admissions decision potentially permits—and even endorses—certain forms of race consciousness. Our analysis is grounded in the observation that the process of developing ML-based systems enables policymakers to calibrate decision making algorithms much more precisely and explicitly in response to specific criticisms of race-conscious affirmative action.", "first_seen": "2026-07-25", "relevance_type": "direct", "confidence": 0.95, "categories": ["ai_in_education", "educational_equity", "education_policy_society"], "reason": "The paper directly examines the use of machine learning in college admissions, the legal constraints on race-conscious algorithms, and their implications for educational equity."}, {"id": "W4410876607", "doi": "10.1016/j.compedu.2026.105723", "title": "The experience of using AI-generated social stories as a behavioral intervention tool for children", "date": "2026-07-20", "year": 2026, "journal": "Computers & Education", "authors": ["Nechami Zaklas", "Tali Gazit"], "cited_by": 1, "abstract": "", "first_seen": "2026-07-25", "relevance_type": "direct", "confidence": 0.95, "categories": ["ai_in_education", "learning_science"], "reason": "The title indicates a study on using AI to generate social stories for behavioral intervention with children, directly examining AI's role in an educational/behavioral context."}, {"id": "W7169613397", "doi": "10.1007/s10648-026-10202-y", "title": "When Can AI Models Explain Learning? Validity Criteria for AI as Cognitive Models in Education", "date": "2026-07-18", "year": 2026, "journal": "Educational Psychology Review", "authors": ["Peng Wang", "Olga Viberg", "Effie Lai-Chong Law", "Samuel Greiff"], "cited_by": 0, "abstract": "Abstract Traditional verbal theories in educational psychology often remain underspecified at the mechanistic level. While they offer rich descriptive constructs and conceptual insights, they provide limited accounts of how learning processes unfold dynamically and causally. Here, “verbal” denotes theories stated in prose and qualitative relations rather than as formal, computational process models. This lack of mechanistic precision constrains rigorous theory testing, limits integration across levels of analysis, and reduces the potential to design interventions grounded in explanatory understanding of learning processes. In this Review, we synthesize an emerging paradigm that treats artificial intelligence (AI) systems not merely as predictive tools or instructional technologies, but as cognitive models of learners, explicit, runnable instantiations of theoretical assumptions about cognition and learning. Our central question is not whether AI systems can serve as cognitive models, but when they should be allowed to count as such. We therefore organize the Review around explicit validity criteria, theoretical grounding, construct validity, mechanistic transparency, alignment with human learning trajectories, error-signature matching, causal-intervention tests, ecological validity, and instructional usefulness, that an AI system must satisfy before its cognitive-model status is granted rather than assumed. We examine how major families of AI models, including neural networks, reinforcement learning agents, cognitive architectures, and large language models, have been used to operationalize core educational constructs such as memory, strategy use, motivation, self-regulation, and social learning. Across these approaches, we highlight how mechanistic transparency, interpretability, and alignment with human learning trajectories and error patterns are essential for explanatory validity. We further discuss methodological tools, such as representation analysis, ablation, and trajectory-level comparison, that enable causal inference about learning mechanisms within models. Finally, we outline key challenges and future directions, including construct validity, ecological realism, individual differences, and ethical accountability. By positioning AI as a theoretical instrument rather than solely an engineering solution, this Review argues that AI-based cognitive models can, when they satisfy these criteria, help transform abstract learning theories into precise, testable, and educationally actionable accounts of how students learn.", "first_seen": "2026-07-25", "relevance_type": "direct", "confidence": 0.95, "categories": ["ai_in_education", "learning_science"], "reason": "The paper directly examines the use of AI as cognitive models of learners in education, proposing validity criteria and discussing implications for educational psychology."}, {"id": "W7169687627", "doi": "10.1111/bjet.70078", "title": "Not a universal benefit: Examining the differential effects of emotional <scp>AI<\/scp> on <scp>L2<\/scp> pre‐service teachers' language learning", "date": "2026-07-18", "year": 2026, "journal": "British Journal of Educational Technology", "authors": ["Zhuo Wang", "Hui Pang"], "cited_by": 0, "abstract": "Abstract While emotional design in educational AI is often presented as a universal benefit, this study challenges that assumption, investigating when, for whom and how it impacts L2 vocabulary learning. This paper reports on the first phase of a larger project, analysing data from a quasi‐experimental study with 147 pre‐service teachers who interacted with either an emotional or a regular AI agent. Data included pre‐/post‐tests, questionnaires and complete AI chat histories. Quantitative analysis revealed no overall difference in vocabulary acquisition or other affective variables. A more nuanced pattern emerged in an exploratory subgroup analysis: contrary to prevailing assumptions, the regular agent—not the emotional one—preserved significantly better learning attitudes ( p = 0.001) and intrinsic motivation ( p = 0.038) for learners with lower baseline proficiency. A possible mechanism is suggested by a significant negative correlation between self‐reported cognitive load and vocabulary scores, found only in the emotional AI group: under high task difficulty, the emotional agent's verbose scaffolding may have added extraneous cognitive load rather than serving as a supportive buffer. We treat this correlational evidence as tentative rather than demonstrated. To explain these divergent outcomes, a qualitative analysis of interaction patterns identified four distinct learner archetypes—from the high‐agency ‘Constructive Inquirer’ to the passive ‘Attentive Pupil’. The findings indicate that the emotional AI's efficacy might be moderated by these profiles; its verbose emotional scaffolding may have added extraneous processing demands for the vulnerable ‘Attentive Pupil’ while being perceived as an inefficient frustration by the task‐oriented ‘Demanding Critic’. The study concludes that a one‐size‐fits‐all approach to emotional AI is suboptimal. Practitioner notes What is already known about this topic Emotional design in digital learning environments is widely considered beneficial for enhancing learner engagement, motivation and positive emotions. Affective AI systems are increasingly being developed for education with the goal of providing personalized and psychologically supportive instruction. Individual learner differences, such as prior knowledge, motivation and confidence, are known to be significant factors that impact the effectiveness of any educational intervention. What this paper adds This paper demonstrates that the benefits of emotional AI are not universal. Its efficacy is highly conditional, with the regular agent—not the emotional one—preserving better learning attitudes and motivation for lower‐proficiency learners under high cognitive load conditions. It tentatively provides a new explanatory framework of four learner archetypes (the Constructive Inquirer, Demanding Critic, Attentive Pupil and Disengaged Bystander) based on observable interaction patterns (agency and questioning effectiveness), which explains why different learners react divergently to the same AI design. It identifies a cognitive load threshold boundary condition: under high task difficulty, verbose emotional scaffolding may exceed learners' working' memory capacity and act as an extraneous processing burden rather than affective support, consistent with experimental evidence on the moderating role of task difficulty in emotional design. It reveals a potential design tension: emotional support is not uniformly beneficial—verbose affective scaffolding intended to help a passive learner (the ‘Attentive Pupil’) may instead add extraneous cognitive load under demanding tasks, while being perceived as an inefficient frustration by a high‐agency, task‐oriented learner (the ‘Demanding Critic’). Implications for practice and/or policy The design and implementation of educational AI must move beyond a ‘one‐size‐fits‐all’ model. Practitioners should select and advocate for tools that can adapt their emotional persona based on user needs, rather than applying a single emotional design universally. The four archetypes can serve as a preliminary diagnostic tool for educators. By observing how students interact with AI, teachers can identify different learner types and provide targeted pedagogical support (e.g., encouraging more agency in an ‘Attentive Pupil’ or helping a ‘Demanding Critic’ reframe the AI as a collaborative partner). For AI developers, the central implication is the need to build adaptive systems that can first diagnose a user's archetype and then dynamically adjust their affective strategy—offering support when needed and becoming an efficient, unobtrusive tool at other times. Educational policy should encourage the development of AI that is not just technologically advanced but also pedagogically sophisticated and emotionally adaptive, ensuring that new technologies serve a diverse student population equitably and effectively.", "first_seen": "2026-07-25", "relevance_type": "direct", "confidence": 0.95, "categories": ["ai_in_education", "educational_equity", "learning_science"], "reason": "The study directly investigates how an emotional AI agent affects L2 vocabulary learning, motivation, and cognitive load, revealing that its benefits are not universal and may disadvantage lower-proficiency learners, thus addressing AI in education and equity implications."}, {"id": "W7169502600", "doi": "10.1016/j.compedu.2026.105722", "title": "Designing effective feedback in video lectures using GenAI: The roles of feedback type and learner agency in error detection", "date": "2026-07-17", "year": 2026, "journal": "Computers & Education", "authors": ["Zhongling Pi", "Yuxiang Cao", "Yiliang Zhang", "Yuxian Ma", "Wanru Cao", "Xiying Li"], "cited_by": 0, "abstract": "", "first_seen": "2026-07-25", "relevance_type": "direct", "confidence": 0.9, "categories": ["ai_in_education", "learning_science"], "reason": "The paper examines generative AI for feedback in video lectures, addressing feedback type and learner agency, which directly pertains to AI-assisted learning and instructional design."}, {"id": "W7168853831", "doi": "10.1126/science.aeh8601", "title": "Social calibration of sycophantic AI—Response", "date": "2026-07-16", "year": 2026, "journal": "Science", "authors": ["Myra Cheng", "Cinoo Lee", "Pranav Khadpe", "Dan Jurafsky"], "cited_by": 0, "abstract": "", "first_seen": "2026-07-25", "relevance_type": "transferable", "confidence": 0.7, "categories": ["ai_and_cognition", "ai_in_education"], "reason": "Techniques to socially calibrate sycophantic AI could be transferred to educational AI systems to reduce over-praise and improve feedback accuracy, directly impacting learning interactions."}, {"id": "W7169095624", "doi": "10.1016/j.learninstruc.2026.102435", "title": "Prompting strategies with generative AI during learning from multiple sources", "date": "2026-07-16", "year": 2026, "journal": "Learning and Instruction", "authors": ["S. Kim", "Matthew T. McCrudden"], "cited_by": 0, "abstract": "", "first_seen": "2026-07-25", "relevance_type": "direct", "confidence": 0.95, "categories": ["ai_in_education", "learning_science"], "reason": "Examines how prompting strategies with generative AI influence learning from multiple sources, directly related to AI in education and learning processes."}, {"id": "W7169023214", "doi": "10.3102/0013189x261467378", "title": "Fifteen Years of Change in High-Quality CTE Participation", "date": "2026-07-16", "year": 2026, "journal": "Educational Researcher", "authors": ["Yerin Yoon", "Shaun M. Dougherty"], "cited_by": 0, "abstract": "In many states, including Massachusetts, demand for high-quality career and technical education (CTE) has grown faster than program supply, raising concerns about equitable access. Using 15 cohorts of administrative data, this brief examines how participation in high-quality CTE has changed across students’ demographic groups. While overall participation and concentration have increased, these gains are unbalanced: Female students have become better represented, while Hispanic/Latino students and English language learners (ELLs) have not. Our findings suggest that underrepresentation among Hispanic/Latino students appears tied to their school access and choice, whereas ELLs face persistent within-school barriers to concentrating in high-quality CTE pathways.", "first_seen": "2026-07-25", "relevance_type": "direct", "confidence": 0.95, "categories": ["educational_equity"], "reason": "Directly examines educational equity by analyzing changes in access to high-quality CTE across demographic groups, highlighting disparities for Hispanic/Latino students and English language learners."}, {"id": "W7168407876", "doi": "10.1038/d41586-026-02016-3", "title": "Improvements in educational opportunities go hand in hand with innovation", "date": "2026-07-15", "year": 2026, "journal": "Nature", "authors": [], "cited_by": 0, "abstract": "The first longitudinal regional atlas of intergenerational educational mobility shows that the subnational regions of Europe in which individuals’ educational opportunities are least dependent on the educational background of their parents tend to have the most innovation, as shown by the number of patents. European regions in which people’s education level is less dependent on their parents’ education generate more patents.", "first_seen": "2026-07-25", "relevance_type": "direct", "confidence": 0.95, "categories": ["educational_equity", "education_policy_society"], "reason": "Directly examines regional educational mobility and its link to innovation, contributing to educational equity research."}, {"id": "W7168349125", "doi": "10.1007/s10648-026-10201-z", "title": "Unveiling Patterns of Generative AI Integration That Enhance Learning: A Systematic Review of Empirical Studies", "date": "2026-07-15", "year": 2026, "journal": "Educational Psychology Review", "authors": ["Shuowen An", "Yu Song", "Bo Jiang"], "cited_by": 0, "abstract": "", "first_seen": "2026-07-25", "relevance_type": "direct", "confidence": 0.95, "categories": ["ai_in_education", "learning_science"], "reason": "Systematic review of empirical studies on generative AI integration for learning enhancement directly addresses AI in education."}, {"id": "W7168395753", "doi": "10.1016/j.econedurev.2026.102814", "title": "Tracing the origins of teacher gender bias", "date": "2026-07-15", "year": 2026, "journal": "Economics of Education Review", "authors": ["George Leckie", "Konstantina Maragkou"], "cited_by": 0, "abstract": "This paper examines whether teachers form gendered expectations that deviate from students’ actual academic performance. We exploit a unique institutional setting in England, where university admissions rely on teacher-predicted grades, and use rich administrative data linking student performance and teacher assessments across multiple STEM and non-STEM subjects. We find that, conditional on achieved grades, teachers systematically predict lower grades for boys relative to observationally similar girls within the same school across all subjects. In the second part of the analysis, we examine the extent to which observable student characteristics account for this pattern. We find that including measures of students’ cross-disciplinary skills reduces the gender gap in predicted grades by up to 70% in non-STEM subjects and fully explains or even reverses it in STEM. These results indicate that what appears to be a pro-girl bias is, at least in part, associated with students’ broader competencies rather than necessarily reflecting differential treatment by teachers. These findings have important implications for the fairness and effectiveness of teacher-based assessments in high-stakes contexts such as university admissions.", "first_seen": "2026-07-25", "relevance_type": "direct", "confidence": 0.95, "categories": ["educational_equity"], "reason": "Directly examines teacher gender bias in high-stakes predicted grades, revealing disparities and implications for fairness in educational assessments, a core educational equity issue."}, {"id": "W7168288578", "doi": "10.1016/j.compedu.2026.105721", "title": "LLM-derived metrics in second language writing assessment: an explainable AI approach", "date": "2026-07-14", "year": 2026, "journal": "Computers & Education", "authors": ["Jingying Hu", "Yan Cong"], "cited_by": 0, "abstract": "Large language models (LLMs) are increasingly used in educational technology for automated writing assessment, yet most applications rely on prompt-based scoring and feedback generation, which often lack transparency, reproducibility, and interpretability. This study investigates whether model-internal LLM representations can provide interpretable and reproducible metrics for second language (L2) writing assessment. We derived surprisal and perplexity from next-token prediction to quantify linguistic predictability and embedding-based similarity to measure semantic coherence across sentences. These metrics were computed at the token, sentence, and discourse levels using three pretrained Chinese language models and evaluated on 1,196 essays written by Chinese L2 learners across four proficiency levels. Their relationships with 11 established linguistic measures of fluency, lexical sophistication, phraseological complexity, and syntactic complexity were also examined. Results showed that surprisal and perplexity generally decreased with proficiency for the two Traditional Chinese-focused models, indicating greater linguistic predictability in more proficient writing, whereas the multilingual model showed weaker sensitivity. Embedding-based similarity increased with proficiency, reflecting stronger semantic coherence. Combining LLM-derived metrics with classical linguistic features improved proficiency classification and prediction beyond either feature set alone. Correlation and qualitative analyses further demonstrated that the proposed metrics capture complementary aspects of writing while revealing conditions under which their interpretations become less reliable. These findings demonstrate the value of interpretable, model-derived metrics for transparent, reproducible, and scalable AI-supported L2 writing assessment, particularly for underrepresented learner populations and lower-resource languages.", "first_seen": "2026-07-25", "relevance_type": "direct", "confidence": 0.95, "categories": ["ai_in_education", "educational_equity"], "reason": "The paper directly investigates interpretable LLM-derived metrics for automated second language writing assessment, with attention to underrepresented learner populations and lower-resource languages, intersecting AI in education and equity."}, {"id": "W7168126575", "doi": "10.1038/s41562-026-02524-2", "title": "Why using AI as a learning coach can improve education", "date": "2026-07-13", "year": 2026, "journal": "Nature Human Behaviour", "authors": ["Tim Fütterer", "Peter Gerjets", "Rebekka Steinhauser", "Armin Fabian", "Nina Udvardi-Lakos", "Jeffrey A. Greene", "Matthew L. Bernacki", "Garvin Brod", "Ulrich Trautwein"], "cited_by": 0, "abstract": "", "first_seen": "2026-07-25", "relevance_type": "direct", "confidence": 0.9, "categories": ["ai_in_education"], "reason": "The title directly states using AI as a learning coach, a clear example of AI in education."}, {"id": "W7168163342", "doi": "10.1038/s41562-026-02529-x", "title": "The unspoken tensions that AI brings to academic collaboration", "date": "2026-07-13", "year": 2026, "journal": "Nature Human Behaviour", "authors": ["Susan Hilbolling", "Janet Rafner"], "cited_by": 0, "abstract": "", "first_seen": "2026-07-25", "relevance_type": "direct", "confidence": 0.85, "categories": ["ai_in_education"], "reason": "The paper addresses how AI impacts academic collaboration, a direct concern for AI in education research."}, {"id": "W7168173698", "doi": "10.1038/s41562-026-02528-y", "title": "AI detection risks undermining academic integrity", "date": "2026-07-13", "year": 2026, "journal": "Nature Human Behaviour", "authors": ["Shixin Zhang", "Xinyou Lv"], "cited_by": 0, "abstract": "", "first_seen": "2026-07-25", "relevance_type": "direct", "confidence": 0.95, "categories": ["ai_in_education"], "reason": "The title directly addresses the impact of AI detection tools on academic integrity, a core topic in AI in education."}, {"id": "W7168144654", "doi": "10.1016/j.compedu.2026.105720", "title": "Rewiring the knowledge field of artificial intelligence in education: A multi-level theoretical perspective on cross-level topic evolution, 2000–2024", "date": "2026-07-13", "year": 2026, "journal": "Computers & Education", "authors": ["Chuang Yang", "Zeqing Xu", "Yu Lin", "Yu Zhang"], "cited_by": 0, "abstract": "", "first_seen": "2026-07-25", "relevance_type": "direct", "confidence": 0.9, "categories": ["ai_in_education"], "reason": "The paper directly studies the field of artificial intelligence in education, examining its knowledge structure and topic evolution."}, {"id": "W7168254654", "doi": "10.3102/0013189x261462516", "title": "How Better FAFSA Changed Federal Aid Applications", "date": "2026-07-13", "year": 2026, "journal": "Educational Researcher", "authors": ["Erik Whitfield", "Oded Gurantz"], "cited_by": 0, "abstract": "The FAFSA Simplification Act altered the federal aid form to minimize barriers to completion and improve aid delivery. Despite these potential benefits, legal, technical, and logistical hurdles led to delays in implementation, creating uncertainty for families and colleges. We descriptively examine changes in California’s FAFSA submissions, using regression analysis to investigate differences in whether students resubmitted the FAFSA. Overall submissions increased modestly, but freshman applications exhibited large declines, with many failing to meet California’s deadline for its generous state aid program. This suggests many students may be enrolling, but without the support of state or federal financial aid. Although FAFSA refiling rates decreased for enrolled students, we observe higher rates of state aid receipt and public college enrollment. JEL Classification Codes: I22, I23, I24, I28", "first_seen": "2026-07-25", "relevance_type": "direct", "confidence": 0.95, "categories": ["educational_equity", "education_policy_society"], "reason": "Examines policy changes affecting financial aid access and equity in college enrollment, directly relevant to educational equity."}, {"id": "W7168178824", "doi": "10.3102/00028312261460584", "title": "Elementary Students’ Conceptualizations of Disability in Written and Illustrated Forms", "date": "2026-07-12", "year": 2026, "journal": "American Educational Research Journal", "authors": ["John Freer", "Monique Somma", "Erica Miklas", "Lillian Scibetta"], "cited_by": 0, "abstract": "Children often develop (mis)understandings of disability at young ages. Forming stereotypes about disability can contribute to ableist attitudes and social exclusion of peers with disabilities. The purpose of this qualitative study was to investigate children’s conceptualizations of disability in written and illustrated forms. Students in grades three to seven from 10 classes ( n = 192) at a midsize inclusive school in Ontario, Canada, were prompted to define the term disability and to draw a character with a disability. As with findings from previous studies, most of the participants’ definitions were rooted in deficit thinking, and students’ drawings tended to be of characters with physical disabilities. Findings less commonly reported with these methods also were identified (e.g., drawings depicting mental health concerns).", "first_seen": "2026-07-25", "relevance_type": "direct", "confidence": 0.9, "categories": ["educational_equity"], "reason": "This qualitative study directly investigates elementary students' conceptualizations of disability and ableist stereotypes, contributing to educational equity research on inclusion."}, {"id": "W7168015445", "doi": "10.1007/s10648-026-10199-4", "title": "The Effects of Intelligent Tutoring Systems on Self-Regulated Learning: A Meta-Analysis", "date": "2026-07-11", "year": 2026, "journal": "Educational Psychology Review", "authors": ["Kaiyu Zhang", "Yi Zhou", "Cheng Zhang", "Jihe Chen"], "cited_by": 0, "abstract": "", "first_seen": "2026-07-25", "relevance_type": "direct", "confidence": 0.9, "categories": ["ai_in_education", "learning_science"], "reason": "The paper directly examines the effects of intelligent tutoring systems (a key AI-in-education technology) on self-regulated learning, directly aligning with the researcher's interest in AI-assisted learning and its outcomes."}, {"id": "W7167918762", "doi": "10.1016/j.compedu.2026.105700", "title": "Educational prompt engineering self-efficacy scale (Ed-PESS): Development and psychometric validation", "date": "2026-07-10", "year": 2026, "journal": "Computers & Education", "authors": ["Fatih Karataş", "Recep GÜR", "Barış Eriçok", "Fatma BAŞARIR", "Lokman TANRIKULU"], "cited_by": 0, "abstract": "", "first_seen": "2026-07-25", "relevance_type": "direct", "confidence": 0.8, "categories": ["ai_in_education"], "reason": "The title indicates a scale measuring self-efficacy in educational prompt engineering, directly related to AI-assisted learning and teaching."}, {"id": "W7167794482", "doi": "10.1037/edu0001063", "title": "Almighty ChatGPT? Development of gifted secondary school students’ AI (mis)conceptions.", "date": "2026-07-09", "year": 2026, "journal": "Journal of Educational Psychology", "authors": ["Ann‐Kathrin Jaggy", "Thorben Jansen", "Tim Fütterer", "Ulrich Trautwein"], "cited_by": 0, "abstract": "The current limitations of generative AI (genAI), such as hallucinations, are well-documented.However, research indicates that young students may misconceive genAI as omniscient.How such a misconception develops remains unclear, particularly as the use of advanced AI grows and exposure to AI increases.Building on certain assumptions from the elaboration likelihood model, this study investigates the \"omniscient-AI\" misconception among gifted secondary school students during a year of rapid AI advancement (2023-2024) by examining its prevalence, persistence, and its association with individual characteristics such as intelligence and personality.A multicohort design yielded crosssectional data across 2 years (N 5 870, Grades 6-8) and longitudinal data for a subsample (n 5 512).Results show that a notable minority (20% in 2023; 16% in 2024) of sixth to eighth graders hold the misconception that genAI is omniscient.Higher intelligence and a greater need for cognition predicted a lower misconception prevalence.Trend analyses suggest a decrease in the prevalence from 2023 to 2024.However, longitudinal analyses revealed no average change in individual students, indicating this trend was driven by a cohort effect rather than individual development, although individual trajectories varied statistically significant.Students with higher intelligence and a higher need for cognition were more likely to revise their conceptions about genAI.The results suggest an emerging Matthew effect, showing that students with a higher capacity and motivation for effortful thinking are better equipped to critically evaluate genAI, potentially exacerbating educational inequalities as those with lower resources remain more susceptible to persistent misconceptions. Educational Impact and Implications StatementThis study finds that a notable number of gifted secondary students believe generative AI (genAI) is all-knowing, a misconception that often persists over time despite increased exposure to AI failures.Students with higher intelligence and a greater enjoyment of thinking are more likely to revise this misconception on their own.These findings show that schools cannot rely on passive experience and must actively teach students how to critically evaluate generative AI's capabilities and limitations.", "first_seen": "2026-07-25", "relevance_type": "direct", "confidence": 0.95, "categories": ["ai_in_education", "educational_equity", "learning_science"], "reason": "Directly investigates secondary students' misconceptions about generative AI and how individual differences predict critical evaluation, with implications for educational inequalities."}, {"id": "W7167823185", "doi": "10.1016/j.econedurev.2026.102815", "title": "Closer in sound, better in learning: linguistic similarity and early literacy in Cameroon", "date": "2026-07-09", "year": 2026, "journal": "Economics of Education Review", "authors": ["Yselle Malah-Kuete"], "cited_by": 0, "abstract": "", "first_seen": "2026-07-25", "relevance_type": "direct", "confidence": 0.9, "categories": ["educational_equity"], "reason": "The paper examines how linguistic similarity affects early literacy in Cameroon, a direct study of language-based educational disparities and equity in learning outcomes."}, {"id": "W7167665150", "doi": "10.1038/d41586-026-01673-8", "title": "I want to see a prison-to-PhD pipeline", "date": "2026-07-08", "year": 2026, "journal": "Nature", "authors": ["Virginia Gewin"], "cited_by": 0, "abstract": "", "first_seen": "2026-07-25", "relevance_type": "direct", "confidence": 0.9, "categories": ["educational_equity", "education_policy_society"], "reason": "The title advocates for educational pathways from prison to PhD, directly addressing educational equity and access for incarcerated individuals."}, {"id": "W7167783469", "doi": "10.3102/0013189x261457608", "title": "Critical Race Aesthetics as a Lens to Notice, Challenge, and Change Images That Undermine the Sense of Belonging Among Minoritized Students", "date": "2026-07-08", "year": 2026, "journal": "Educational Researcher", "authors": ["ChanMin Kim"], "cited_by": 0, "abstract": "In this review/essay article, the author argues that education researchers and educators should attend to visual elements in classrooms as ambient identity cues to allow for socio-spatial belonging among minoritized students. The author proposes the application of critical race aesthetics to notice, challenge, and change inequitable ambient cues that (re)create oppression and privilege. The author presents case vignettes from research with elementary STEM teachers and Black and Brown students to illustrate the role of images in meaning-making of STEM spaces. The author offers methods to apply the lens of critical race aesthetics to teacher and school leader education to improve equity. The author discusses implications for education research in terms of advancing applied theories and equity effort.", "first_seen": "2026-07-25", "relevance_type": "direct", "confidence": 0.95, "categories": ["educational_equity"], "reason": "Directly addresses educational equity by proposing a framework to challenge ambient visual cues that undermine belonging among minoritized students."}, {"id": "W7167590921", "doi": "10.1038/d41586-026-02110-6", "title": "Listen to Gen Z when it comes to AI in education", "date": "2026-07-07", "year": 2026, "journal": "Nature", "authors": ["Ian Robertson", "Vincent C. Müller", "Eleonora Catena"], "cited_by": 0, "abstract": "", "first_seen": "2026-07-25", "relevance_type": "direct", "confidence": 0.85, "categories": ["ai_in_education"], "reason": "Title directly addresses AI in education from the perspective of Gen Z learners."}, {"id": "W7167591156", "doi": "10.1038/s44159-026-00594-7", "title": "Ethnic discrimination in norm enforcement", "date": "2026-07-07", "year": 2026, "journal": "Nature Reviews Psychology", "authors": ["Kasper Otten"], "cited_by": 0, "abstract": "", "first_seen": "2026-07-25", "relevance_type": "transferable", "confidence": 0.7, "categories": ["educational_equity"], "reason": "Findings on ethnic discrimination in norm enforcement can inform strategies to reduce biased disciplinary practices in schools."}, {"id": "W7167613696", "doi": "10.1038/d41586-026-02105-3", "title": "‘Humanizer’ tool can erase signs of AI-written text — alarming scientists", "date": "2026-07-07", "year": 2026, "journal": "Nature", "authors": ["Edward Chen"], "cited_by": 0, "abstract": "", "first_seen": "2026-07-25", "relevance_type": "direct", "confidence": 0.9, "categories": ["ai_in_education"], "reason": "The title directly addresses a tool that masks AI-generated text, which is highly relevant to academic integrity and AI detection in education settings."}, {"id": "W7167661887", "doi": "10.3102/0013189x261462499", "title": "Postsecondary Gaps in Recovery From the COVID-19 Pandemic: Evidence From Public Colleges and Universities", "date": "2026-07-07", "year": 2026, "journal": "Educational Researcher", "authors": ["Dora Gicheva", "Julie Edmunds", "Bryan C. Hutchins", "Nir Eilam", "Nina Arshavsky"], "cited_by": 0, "abstract": "We study changes in postsecondary student performance during and after the COVID-19 pandemic using administrative data on all 2015–2022 high school graduates in North Carolina who enrolled in an in-state public institution. Successful course completion rates increased briefly at 4-year institutions at the start of the pandemic, but at both 2- and 4-year institutions, success rates and credit earning decreased for later cohorts. These declines have persisted for certain groups, including students from underrepresented racial and ethnic groups, economically disadvantaged and academically weaker students, as well as female students. The findings point to ongoing academic challenges faced by vulnerable college student populations in the postpandemic period.", "first_seen": "2026-07-25", "relevance_type": "direct", "confidence": 0.95, "categories": ["educational_equity"], "reason": "This study directly examines educational equity by documenting persistent achievement gaps for underrepresented, economically disadvantaged, and academically weaker students in postsecondary education."}, {"id": "W7167600565", "doi": "10.3102/01623737261462496", "title": "Promoting Academic Success Through University Microgrants for Students", "date": "2026-07-07", "year": 2026, "journal": "Educational Evaluation and Policy Analysis", "authors": ["Katharine M. Broton", "Solomon Fenton-Miller", "Nicholas A. Bowman"], "cited_by": 0, "abstract": "The high price of college attendance remains a barrier to success for students from low- and moderate-income families. In response, institutions have introduced microgrants—small, off-cycle, need-based grants for undergraduates—to support student success. However, evidence on their effectiveness is limited. Using extensive administrative and survey data, we apply doubly robust quasi-experimental matching methods to estimate the relationships between microgrants and academic outcomes over 4 years. Findings indicate that grant recipients achieved higher grade point averages (GPAs), earned more credits, had better retention rates, and graduated at higher rates than their observably similar peers. These findings have important implications for equity efforts in the current sociopolitical context, as students from historically underserved groups were more likely to receive microgrants despite their universal design.", "first_seen": "2026-07-25", "relevance_type": "direct", "confidence": 0.95, "categories": ["educational_equity", "education_policy_society"], "reason": "This paper directly examines the impact of need-based microgrants on academic outcomes for historically underserved students, addressing educational equity."}, {"id": "W7167464021", "doi": "10.1038/d41586-026-01358-2", "title": "Universities are relying on AI-detection software to catch cheating. How well do the programs work?", "date": "2026-07-06", "year": 2026, "journal": "Nature", "authors": ["Anna McKie"], "cited_by": 0, "abstract": "", "first_seen": "2026-07-25", "relevance_type": "direct", "confidence": 0.85, "categories": ["ai_in_education"], "reason": "The title directly addresses the use and efficacy of AI-detection software for academic integrity in universities, a core AI-in-education topic."}, {"id": "W7167479343", "doi": "10.1073/pnas.2536089123", "title": "Educational expansion and the hidden reversal of the Flynn effect—Differential trends across socioeconomic strata", "date": "2026-07-06", "year": 2026, "journal": "Proceedings of the National Academy of Sciences", "authors": ["Bernt Bratsberg", "Anders M. Fjell", "Ole J. Rogeberg", "Kristine B. Walhovd"], "cited_by": 0, "abstract": "In recent decades, the United States and several European countries have seen a plateau and reversal of the population-level gains in cognitive test scores that accumulated over the 20th century-the Flynn effect. We examined whether the Flynn effect and its reversal-declining mean scores across cohorts-differ by socioeconomic status, and whether changes in education can account for this. Using compulsory military conscription cognitive tests linked to administrative records with near-complete population coverage, we studied 579,379 Norwegian men from 25 birth cohorts (1967-1991). Trend reversals appeared first among sons of high-income fathers, with low- and middle-income groups peaking later and showing smaller postpeak declines. These socioeconomic differences were consistent with convergence in educational attainment at conscription: across paternal-income ranks, cohort changes in test scores aligned with cohort gains in education at conscription age, with estimated schooling effect sizes in line with quasi-experimental evidence. Results were robust to adjustment for parental education, and birth weight and height at testing as proxies for prenatal conditions and childhood nutrition. Together, the findings suggest an underlying population-level decline in cognitive scores that began earlier than previously assumed but was temporarily offset in lower-income strata by expanding educational attainment. After educational expansion plateaued, scores declined across all groups, most steeply among higher-income strata. Upper-secondary education completion thus emerges as a potential lever for improving cognitive performance and reducing income-related disparities in cognitive ability scores, while highlighting that broader societal pressures on cognitive test performance may have started earlier than recognized.", "first_seen": "2026-07-25", "relevance_type": "direct", "confidence": 0.95, "categories": ["educational_equity"], "reason": "This paper directly examines socioeconomic disparities in cognitive test score trends and the role of educational expansion, which is central to educational equity research."}, {"id": "W7167463379", "doi": "10.3102/0013189x261457605", "title": "Holding Out or Holding Back? Shifts in Kindergarten Redshirting and Retention Since the COVID-19 Pandemic", "date": "2026-07-06", "year": 2026, "journal": "Educational Researcher", "authors": ["Rachel Fidel", "Kenneth Shores", "Anamarie Whitaker"], "cited_by": 0, "abstract": "This study examined changes in kindergarten redshirting and retention practices in Delaware since the COVID-19 pandemic. Using student-level data from fall 2010 to fall 2023, we found that redshirting rates spiked dramatically in fall 2021, with the largest relative increases among historically underrepresented groups including Black, Hispanic, and low-income students. Retention showed a long-term declining trend that was disrupted only in 2021, when rates returned to pre-pandemic levels. These patterns suggest both practices operated as parallel strategies for securing more typical kindergarten experiences. These demographic shifts have important implications for classroom composition and instructional planning in post-pandemic elementary education.", "first_seen": "2026-07-25", "relevance_type": "direct", "confidence": 0.95, "categories": ["educational_equity", "education_policy_society"], "reason": "Directly examines shifts in kindergarten redshirting and retention practices by race and income, revealing equity implications for post-pandemic elementary education."}, {"id": "W7167468087", "doi": "10.3102/0013189x261461449", "title": "An Anxious Teacher: Math Teaching Anxiety and Student Achievement", "date": "2026-07-06", "year": 2026, "journal": "Educational Researcher", "authors": ["NaYoung Hwang", "Suzanne Graham", "Mark Berends"], "cited_by": 0, "abstract": "This study combines state-level teacher survey data with administrative records for Indiana students in Grades 3 through 8 to examine the association between math teaching anxiety and student math achievement. We find that students from underserved backgrounds, including those from low-income, Black, and Hispanic families, are more likely to be assigned to teachers who report higher levels of math teaching anxiety. Student fixed-effects models show that math teaching anxiety is associated with lower student math achievement, with stronger negative associations for female students, English language learners, lower-achieving students, and Hispanic and Asian students. These findings point to unequal access to high-quality teachers and suggest that certain groups of students are more vulnerable to math teaching anxiety.", "first_seen": "2026-07-25", "relevance_type": "direct", "confidence": 0.95, "categories": ["educational_equity"], "reason": "The paper examines unequal access to high-quality teaching based on teacher math anxiety and its differential impact on student achievement across subgroups, a direct educational equity concern."}, {"id": "W7167471729", "doi": "10.1037/edu0001056", "title": "Debunking the learning styles neuromyth: No effects of learning styles on recognition accuracy in primary education students.", "date": "2026-07-06", "year": 2026, "journal": "Journal of Educational Psychology", "authors": ["Μαριέττα Παπαδάτου-Παστού", "Anna Κ. Touloumakos", "Efthalia Theotokatou"], "cited_by": 0, "abstract": "", "first_seen": "2026-07-25", "relevance_type": "direct", "confidence": 0.95, "categories": ["learning_science"], "reason": "The paper directly investigates a widely held belief about learning (learning styles) and its impact on primary education students, which is central to education research."}, {"id": "W7167505732", "doi": "10.3102/01623737261445984", "title": "Bulwark or Barrier? The Effect of Academic Criteria-Based Reclassification on the High School Outcomes of Multilingual Learners in Texas", "date": "2026-07-06", "year": 2026, "journal": "Educational Evaluation and Policy Analysis", "authors": ["Shirley H. Xu", "Coral Flanagan", "Diana Quintero"], "cited_by": 0, "abstract": "English learner (EL) classification can provide multilingual students (MLs) with key supports while limiting access to important educational opportunities. To determine when students are ready to exit EL status, some states require students to meet academic criteria in addition to demonstrated English proficiency. However, few studies empirically examine these criteria, which may become increasingly restrictive in upper grades. We use administrative data from Texas and a regression discontinuity (RD) design to estimate the effect of using academic criteria to reclassify students at the end of eighth grade. Reclassified students earn more advanced credits, but graduate high school at lower rates, indicating a need for greater course access for EL-classified students and increased support for former ML-ELs.", "first_seen": "2026-07-25", "relevance_type": "direct", "confidence": 0.95, "categories": ["educational_equity", "education_policy_society"], "reason": "Examines how academic criteria for reclassifying English learners affect high school outcomes, directly addressing educational equity and policy impacts on multilingual students."}, {"id": "W7167350132", "doi": "10.1007/s10648-026-10174-z", "title": "A Mixed-methods Study of How to Improve Primary-secondary Transitions in England: Combining Academic Research with Policy and Practice Consultation", "date": "2026-07-04", "year": 2026, "journal": "Educational Psychology Review", "authors": ["Charlotte Louise Bagnall", "David Edge", "Emily Banwell", "R. Seymour", "Nicholas Garnett", "Carla Mason", "Margarita Panayiotou", "Divya Jindal‐Snape", "Rhiannon Packer", "Kieran Hodgkin", "Craig Skerritt", "Caitlyn Donaldson", "James Birchwood", "A. McAreavey", "Emma Cunningham"], "cited_by": 0, "abstract": "Primary-secondary school transitions are critical periods in children's educational and emotional development, which pose heightened risk for poor attainment, attendance, social adjustment, and mental health, particularly for vulnerable children. Yet, the multiple challenges presented during this time remain difficult for English schools to manage without clear statutory guidance. Government reports consistently identify transitions as a systemic weakness, while practitioners report uncertainty about what to prioritise, resulting in highly variable, locally interpreted provision. It is important that best practice guidance is developed, drawing on evidence from research, policy, and practice, to inform an evidence-informed transitions strategy in England. To narrow this gap, the present research takes an exploratory sequential mixed-methods design, triangulating multiple stakeholder perspectives and multidisciplinary evidence to develop an evidence-based framework with policy recommendations. A systematic literature review was first conducted to explore key priority areas identified within existing research. Building on these insights, 10 round-table discussions were conducted to aggregate multi-disciplinary perspectives of 52 experts within educational practice, research, and policy, nationwide. Data were analysed using Thematic Framework Analysis, to identify barriers and facilitators in implementing high-quality primary-secondary school transitions provision, and what key priority areas should be included in national strategy. Meta-inferences were then drawn to develop an evidence-based framework outlining five policy recommendations, with implementation proposals of how each might be enacted in practice. This research offers a conceptual foundation to inform policy and could have practical utility for informing high-quality research and practice. Practical and contextual challenges associated with introducing a statutory transitions strategy in England are considered.", "first_seen": "2026-07-25", "relevance_type": "direct", "confidence": 0.95, "categories": ["educational_equity", "education_policy_society"], "reason": "The paper addresses educational disparities during school transitions for vulnerable children and proposes evidence-based policy recommendations, directly contributing to educational equity research."}, {"id": "W7167287501", "doi": "10.1111/bjet.70077", "title": "A balance between stability and flexibility: Adaptive patterns of self‐regulated learning processes shape game‐based learning", "date": "2026-07-03", "year": 2026, "journal": "British Journal of Educational Technology", "authors": ["Elizabeth B. Cloude", "S Huber", "Jingwei Wei", "Bianca Esmanhoto", "Muhterem Dindar", "Manuel Ninaus", "Kristian Kiili"], "cited_by": 0, "abstract": "Abstract To ensure learning efficiency in game‐based learning (GBL), learners must regulate cognitive, affective, metacognitive and motivational (CAMM) processes, collectively known as self‐regulated learning (SRL). SRL is dynamic and non‐linear, characterized by regulatory patterns and CAMM interactions that lead to macro‐level SRL behaviours. In this paper, we explore SRL as a complex system by analysing patterns and interactions among CAMM processes during GBL and examine their relation to learning outcomes. Thirty‐seven ( n = 37) healthy adults used Antidote COVID‐19, a GBL environment designed to increase emotional engagement and biology knowledge. To define momentary CAMM processes, subjective measures of cognitive, affective and metacognitive states via think‐ and emote‐alouds were synchronized with two physiological correlates of motivation: intensity of facial expressions (arousal) and skin conductance response. Sequence analysis and recurrence quantification defined the regularity of patterns within CAMM components, and transfer entropy estimated concurrent interactions between CAMM components. Our results indicated a quadratic relationship between the turbulence (a measure of regularity) of cognitive, affective and metacognitive (CAM) state transitions (via think‐ and emote‐aloud methods) provided the best fit, explaining 31% of variability in learning. This highlights an optimal balance between stability and flexibility in CAM state transitions that were beneficial for learning. However, physiological correlates of motivation were not predictive regarding learning performance. This lack of predictive capability of the considered measures may reflect their limitations in capturing nuanced motivation dynamics relevant to learning or suggest that motivation's role in learning is predominantly mediated through cognitive and metacognitive engagement rather than directly influencing outcomes. Practitioner notes What is already known about this topic Game‐based learning (GBL) is a promising intervention for improving science knowledge, but it places high self‐regulatory demands on learners. Learners must manage cognitive, affective, motivational and metacognitive (CAMM) processes to ensure GBL efficiency; otherwise known as self‐regulated learning (SRL). Prior research has shown that CAMM processes are each important for learning in games, but they are often studied in isolation rather than as interacting processes over time. What this paper adds This study conceptualizes SRL in GBL as a complex system utilizing mixed multimodal data, emphasizing patterns and interactions among CAMM processes rather than static averages. Results show that learning is maximized when learners exhibit an optimal balance between stability and flexibility in their cognitive, affective and metacognitive state transitions, neither overly rigid nor overly random regulation patterns. Cognitive, affective and metacognitive processes (assessed via think–/emote‐alouds) were strongly related to learning gain, whereas physiological indicators of motivation alone were not predictive. Implications for practice and/or policy Designers of GBL environments should support adaptive regulation, encouraging learners to flexibly shift SRL strategies and emotions while maintaining coherence in their learning process. Educators and researchers should be cautious about relying solely on physiological measures (eg, arousal) for assessing learning effectiveness, as these may not capture meaningful regulatory dynamics. Policies and evaluation frameworks for educational games should prioritize tools and analytics that capture process‐level SRL patterns over time, rather than focusing exclusively on outcomes or isolated behavioural indicators.", "first_seen": "2026-07-25", "relevance_type": "direct", "confidence": 0.9, "categories": ["ai_in_education", "learning_science"], "reason": "The paper directly studies self-regulated learning processes in a game-based learning environment, relevant to AI in education as educational technology for learning."}, {"id": "W7167067699", "doi": "10.1126/science.aek1435", "title": "A classroom contract for AI", "date": "2026-07-02", "year": 2026, "journal": "Science", "authors": ["Tomasz Głowacki"], "cited_by": 0, "abstract": "", "first_seen": "2026-07-25", "relevance_type": "direct", "confidence": 0.8, "categories": ["ai_in_education"], "reason": "The title directly indicates the paper addresses the use of AI in classroom settings, likely proposing guidelines for integrating AI into education."}, {"id": "W7167806944", "doi": "10.1016/j.tics.2026.06.004", "title": "Is AI making us stupid?", "date": "2026-07-01", "year": 2026, "journal": "Trends in Cognitive Sciences", "authors": ["Trent N. Cash", "Megan O. Kelly", "Brooke N. Macnamara", "Evan F. Risko"], "cited_by": 0, "abstract": "", "first_seen": "2026-07-25", "relevance_type": "direct", "confidence": 0.85, "categories": ["ai_in_education", "ai_and_cognition"], "reason": "The title directly questions the impact of AI on human intelligence, which is central to AI in education and cognitive effects of AI use."}, {"id": "W7166823997", "doi": "10.1016/j.compedu.2026.105707", "title": "A community of inquiry perspective on human–AI co-facilitation within micro-blended learning", "date": "2026-07-01", "year": 2026, "journal": "Computers & Education", "authors": ["Zilong Pan", "Zilu Jiang", "Shen Ba", "Kui Xie"], "cited_by": 0, "abstract": "", "first_seen": "2026-07-25", "relevance_type": "direct", "confidence": 0.9, "categories": ["ai_in_education", "learning_science"], "reason": "Title explicitly concerns human-AI co-facilitation in a blended learning context, directly within AI-in-education research."}, {"id": "W7168270823", "doi": "10.1016/j.compedu.2026.105719", "title": "AI-Generated Podcasts and Learning Outcomes: The Role of Behavioral Engagement and Scaffolding", "date": "2026-07-01", "year": 2026, "journal": "Computers & Education", "authors": ["Erfan Rezvani"], "cited_by": 0, "abstract": "", "first_seen": "2026-07-25", "relevance_type": "direct", "confidence": 0.85, "categories": ["ai_in_education", "learning_science"], "reason": "This study directly examines the effect of AI-generated educational podcasts on learning outcomes, with behavioral engagement and scaffolding as mediating or moderating factors."}, {"id": "W7168294044", "doi": "10.1016/j.compedu.2026.105716", "title": "Developing L2 writing student self-assessment literacy through AI-generated feedback and AI chain-of-thought: An action research study with lower-proficiency university EFL learners", "date": "2026-07-01", "year": 2026, "journal": "Computers & Education", "authors": ["Pan Ye", "Shulin Yu", "Icy Lee", "Chenggang Liang"], "cited_by": 0, "abstract": "", "first_seen": "2026-07-25", "relevance_type": "direct", "confidence": 0.9, "categories": ["ai_in_education", "learning_science"], "reason": "The study investigates AI-generated feedback and AI chain-of-thought to develop self-assessment literacy in L2 writing, directly combining AI and education."}, {"id": "W7169816075", "doi": "10.1016/j.compedu.2026.105724", "title": "Artificial Intelligence in Educational Leadership: A PRISMA-Guided Bibliometric Review and Agenda for Future Research", "date": "2026-07-01", "year": 2026, "journal": "Computers & Education", "authors": ["Chuan-Chung Hsieh", "Hope Wilfred Banda", "Hui‐Chieh Li"], "cited_by": 0, "abstract": "", "first_seen": "2026-07-25", "relevance_type": "direct", "confidence": 0.9, "categories": ["ai_in_education", "education_policy_society"], "reason": "The paper reviews AI applications in educational leadership, which is a core aspect of AI in education research."}, {"id": "W7170086966", "doi": "10.1016/j.iheduc.2026.101103", "title": "The double-edged sword effect of AI use on college students' learning engagement", "date": "2026-07-01", "year": 2026, "journal": "The Internet and Higher Education", "authors": ["Du Jingwen", "Wang Jun"], "cited_by": 0, "abstract": "", "first_seen": "2026-07-25", "relevance_type": "direct", "confidence": 0.95, "categories": ["ai_in_education", "learning_science"], "reason": "Directly investigates the dual effects of AI use on college students' learning engagement, central to AI in education research."}, {"id": "W7166508423", "doi": "10.1038/d41586-026-01672-9", "title": "How AI can crack open the ‘hidden curriculum’ for neurodivergent students", "date": "2026-06-29", "year": 2026, "journal": "Nature", "authors": ["Marisa Chrysochoou", "Keivan Stassun"], "cited_by": 0, "abstract": "", "first_seen": "2026-07-25", "relevance_type": "direct", "confidence": 0.9, "categories": ["ai_in_education", "educational_equity"], "reason": "The title directly indicates a focus on using AI to address the 'hidden curriculum' for neurodivergent students, combining AI in education with equity and inclusion."}, {"id": "W7166521153", "doi": "10.1037/edu0001066", "title": "Hierarchical nature of arithmetic skills: Similarities and differences between arithmetic operations.", "date": "2026-06-29", "year": 2026, "journal": "Journal of Educational Psychology", "authors": ["Jarno Rautiainen", "Tuija Aro", "Mikko Aro", "Asko Tolvanen", "Tuire Koponen"], "cited_by": 0, "abstract": "", "first_seen": "2026-07-25", "relevance_type": "direct", "confidence": 0.7, "categories": ["learning_science"], "reason": "The paper investigates the structure of arithmetic skills, directly informing how learning hierarchies are organized in education."}, {"id": "W7166540369", "doi": "10.1037/edu0001059", "title": "Socioeconomic status and literacy achievement: A meta-analysis of correlations and disparities in reading and writing skills.", "date": "2026-06-29", "year": 2026, "journal": "Journal of Educational Psychology", "authors": ["Yucheng Cao", "Young‐Suk Grace Kim", "Yuemeng Wang"], "cited_by": 0, "abstract": "", "first_seen": "2026-07-25", "relevance_type": "direct", "confidence": 0.95, "categories": ["educational_equity"], "reason": "This meta-analysis examines disparities in literacy achievement by socioeconomic status, directly addressing educational equity in reading and writing skills."}, {"id": "W7166572309", "doi": "10.3102/0013189x261463238", "title": "Developmental Timing of Educational Opportunities for Children in Low-Income Households", "date": "2026-06-29", "year": 2026, "journal": "Educational Researcher", "authors": ["Eric Dearing", "Henrik Daae Zachrisson", "Andres S. Bustamante", "Deborah Lowe Vandell"], "cited_by": 0, "abstract": "Extending findings from a 26-year longitudinal study of educational opportunity, we examine whether opportunities are related to the educational attainment and earnings of children from lower-income households ( n = 226) as a function of when in a child’s development they occur. We compare the predictive power of opportunities accrued within three key developmental stages—early childhood, middle childhood, or adolescence—with the combined power of opportunities accrued across these stages. Our findings point to the value of educational opportunity in all three stages, particularly for educational attainment.", "first_seen": "2026-07-25", "relevance_type": "direct", "confidence": 0.95, "categories": ["educational_equity"], "reason": "Directly examines how timing of educational opportunities affects outcomes for low-income children, central to educational equity research."}, {"id": "W4410858952", "doi": "10.1177/00380407261457391", "title": "Hidden Advantage along the Pipeline: Family Wealth and Educational Transitions from High School through Graduate School", "date": "2026-06-29", "year": 2026, "journal": "Sociology of Education", "authors": ["Wesley Jeffrey", "Christian Smith", "Laura T. Hamilton"], "cited_by": 0, "abstract": "Research shows a link between wealth and educational attainment, but little work has examined wealth relationships from high school degree through graduate degree completion. We use data from the National Longitudinal Survey of Youth 1997 to study when and how wealth may advantage students along their entire educational trajectory. Using sequential logistic regression models (“Mare models”), we find that across transitions, wealth relationships are separate from income and parental education relationships. As observed for other socioeconomic dimensions, wealth relationships decrease at the transition to graduate school entry. However, we show that the wealth relationship substantially increases at the graduate degree completion transition, running counter to the waning pattern found for family income and parental education. We also reveal that, like other socioeconomic dimensions, these wealth relationships partially attenuate when we include early indicators of academic performance differentials. Our findings thus shed new light on the nature of wealth-based educational inequality in the United States.", "first_seen": "2026-07-25", "relevance_type": "direct", "confidence": 0.95, "categories": ["educational_equity", "education_policy_society"], "reason": "Directly examines wealth-based educational inequality in attainment transitions, contributing to understanding of socioeconomic disparities in education."}, {"id": "W7166542713", "doi": "10.3102/01623737261453349", "title": "The Model Itself or Something Else? Whether and How the Transition from Traditional Preparation to Teacher Residency Model Impacts the Outcomes of Graduates", "date": "2026-06-29", "year": 2026, "journal": "Educational Evaluation and Policy Analysis", "authors": ["Matthew Truwit", "Matthew Ronfeldt"], "cited_by": 0, "abstract": "Studies of teacher residencies highlight their potential to increase the diversity and persistence of the workforce while addressing district staffing shortages. However, prior research is largely unable to directly attribute these promising trends to the programmatic elements of the residency model itself. Using a novel statewide survey and leveraging temporal variation in when predominantly undergraduate traditional teacher preparation programs across Tennessee reported becoming residencies, we estimate the causal impacts of adoption of the model on recruitment, employment, retention, and effectiveness. We generate skepticism that any improvements in diversity, employment, and retention stem from this transition; however, we find suggestive evidence that adoption may increase the instructional effectiveness and—somewhat surprisingly—the likelihood of migration across schools and districts of graduates.", "first_seen": "2026-07-25", "relevance_type": "direct", "confidence": 0.95, "categories": ["educational_equity", "education_policy_society"], "reason": "The paper evaluates teacher residency programs' impact on workforce diversity, retention, and effectiveness, directly addressing equity in teacher preparation and staffing."}, {"id": "W7166589218", "doi": "10.3102/00028312261457764", "title": "Articulating Concerns in School Rezoning: Disrupted Expectations, Discursivity, and Voting Outcomes", "date": "2026-06-28", "year": 2026, "journal": "American Educational Research Journal", "authors": ["Andrene J. Castro", "Jeffrey Wooten"], "cited_by": 0, "abstract": "School rezoning often generates concerns that drive resistance to boundary changes, but how this resistance translates into voting outcomes is less understood. This study introduces a three-part concerns framework for interpreting how families publicly articulate rezoning opposition. We examined concerns as responses to disrupted expectations, as discursive constructions, and as voting processes. Thematic analysis of more than 6,000 survey comments revealed that concerns about neighborhood dynamics, transportation, and school feeder patterns dominated responses, functioning as political tools that obscured underlying demographic anxieties. Although families avoided explicit mention of race or class, analysis of voting patterns showed systematic opposition to proposals increasing school diversity. These findings demonstrate that concerns are complex political constructions, offering school leaders practical insights for navigating opposition.", "first_seen": "2026-07-25", "relevance_type": "direct", "confidence": 0.95, "categories": ["educational_equity", "education_policy_society"], "reason": "This study directly examines educational equity by analyzing resistance to school rezoning, revealing how concerns about diversity are obscured in public discourse and how voting patterns oppose increased school diversity."}, {"id": "W7166305111", "doi": "10.1016/j.compedu.2026.105706", "title": "Operationalizing cognitive apprenticeship through generative AI pedagogical agents: Proactive and contextualized guidance in simulation-based learning", "date": "2026-06-27", "year": 2026, "journal": "Computers & Education", "authors": ["Po-Yao Chao", "Yu-Chen Cheng", "Kuan-Chieh Chen", "Ying-Siou Chen", "Shu-Hao Wu", "Chi-Ting Wen", "Chin-Ling Weng", "Pei-Jung Tsai", "Chia‐Hui Chang", "Hui-Chun Hung", "Chen‐Chung Liu"], "cited_by": 0, "abstract": "", "first_seen": "2026-07-25", "relevance_type": "direct", "confidence": 0.95, "categories": ["ai_in_education", "learning_science"], "reason": "The title directly addresses using generative AI agents for cognitive apprenticeship in simulation-based learning, which is a core AI-in-education topic."}, {"id": "W7166142993", "doi": "10.3102/00346543261455292", "title": "Young Carers’ Experiences in School: A Qualitative Systematic Review", "date": "2026-06-26", "year": 2026, "journal": "Review of Educational Research", "authors": ["Andrea Reupert", "Kim Foster", "Lingling Chen", "Darryl Maybery"], "cited_by": 0, "abstract": "Young carers under the age of 18 years provide informal care for family members with a disability, physical or mental illness, or substance misuse issue in addition to a managing their schoolwork and other responsibilities. Caring responsibilities may negatively impact their wellbeing and educational and social opportunities. Although schools are essential in shaping the educational experiences of young carers, there is a lack of awareness about them and their needs as a distinct group, along with insufficient support from teachers and school staff. The overall aim of this qualitative systematic review was to explore the experiences of young carers in school settings from the perspective of the young carer and the views of their parents and school staff. Following a systematic search process, 17 peer-reviewed, qualitative studies met the inclusion criteria. Findings highlight the dual nature of schools in young carers’ lives, offering support and stability while also posing challenges involving stigma, bullying, and inconsistent and reactive school support. Fear of judgement often prevented young carers from disclosing their caring role to others. Schools should implement proactive policies, including staff training, peer support, and flexible learning, and balance high expectations with empathy to ensure that young carers are recognized and supported.", "first_seen": "2026-07-25", "relevance_type": "direct", "confidence": 0.95, "categories": ["educational_equity"], "reason": "Explores inequities in school experiences and support for young carers, an underserved student group, directly addressing educational equity."}, {"id": "W7165941524", "doi": "10.3102/0013189x261461521", "title": "Housing Instability and High School Completion: A Research Brief", "date": "2026-06-25", "year": 2026, "journal": "Educational Researcher", "authors": ["Sophie Bandarkar", "Peter Hepburn"], "cited_by": 0, "abstract": "Residential instability is linked to lower educational attainment, but research—particularly quantitative research—often overlooks the causes underlying residential moves and the differential effects of forced and voluntary mobility. Using longitudinal data from the Future of Families and Child Wellbeing Study, we examine how different trajectories of residential mobility shape high school completion among low-income children. We find that both forced and voluntary moves are associated with lower graduation rates. Repeated moves and moves during adolescence are also linked to lower graduation rates, while eviction-specific moves are not uniquely predictive of graduation.", "first_seen": "2026-07-25", "relevance_type": "direct", "confidence": 0.95, "categories": ["educational_equity", "education_policy_society"], "reason": "Directly examines how housing instability—a socioeconomic factor—affects high school completion, a key educational equity outcome."}, {"id": "W7166007058", "doi": "10.3102/00028312261453572", "title": "Untapped Potential? Understanding the Paraeducator-to-Teacher Pipeline and Its Potential for Diversifying the Teacher Workforce", "date": "2026-06-25", "year": 2026, "journal": "American Educational Research Journal", "authors": ["Andrew Camp", "Gema Zamarro", "Josh B. McGee"], "cited_by": 0, "abstract": "Paraeducators are among the largest categories of public education employees and are increasingly seen as a pool of potential teachers. However, little is known about paraeducator-to-teacher transitions. Using statewide administrative data, we show that while paraeducators may be more racially/ethnically diverse than the teacher workforce, Black and Hispanic paraeducators are less likely than White paraeducators to transition into teaching. We additionally show that teachers with paraeducator experience are similarly effective to teachers without paraeducator experience. Lastly, we use simulations to show that the potential for the paraeducator-to-teacher pipeline to diversify the teaching profession may be limited unless they are highly targeted. Our results have policy design implications for efforts to expand the paraeducator-to-teacher pipeline or to diversify the teacher workforce.", "first_seen": "2026-07-25", "relevance_type": "direct", "confidence": 0.95, "categories": ["educational_equity", "education_policy_society"], "reason": "Directly addresses racial/ethnic disparities in the paraeducator-to-teacher pipeline and implications for diversifying the teacher workforce, an educational equity issue."}]};
